<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x * 32, player.y * 32, 32, 32);
        }

        function drawTiles() {
            for (const [key, tile] of Object.entries(tiles)) {
                ctx.fillStyle = tile.crop === 'seed' ? 'brown' : 'green';
                ctx.fillRect(key.split(',')[0] * 32, key.split(',')[1] * 32, 32, 32);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'yellow';
            ctx.font = '16px Arial';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        }

        function drawDay() {
            ctx.fillStyle = 'blue';
            ctx.font = '16px Arial';
            ctx.fillText(`Day: ${day}`, 10, 60);
        }

        function update() {
            requestAnimationFrame(update);
            day++;
            drawPlayer();
            drawTiles();
            drawInventory();
            drawDay();
        }

        document.addEventListener('keydown', (e) => {
            switch (e.key) {
                case 'ArrowUp':
                    player.y -= 1;
                    break;
                case 'ArrowDown':
                    player.y += 1;
                    break;
                case 'ArrowLeft':
                    player.x -= 1;
                    break;
                case 'ArrowRight':
                    player.x += 1;
                    break;
                case 'p':
                    if (inventory.seeds > 0) {
                        tiles[`${player.x},${player.y}`] = { crop: 'seed', stage: 0 };
                        inventory.seeds--;
                    }
                    break;
                case 't':
                    // Implement time advancement logic here
                    break;
                case 'h':
                    if (tiles[`${player.x},${player.y}`] && tiles[`${player.x},${player.y}`].crop === 'seed') {
                        tiles[`${player.x},${player.y}`] = { crop: 'crops', stage: 1 };
                        inventory.crops++;
                        inventory.seeds--;
                    }
                    break;
                case 's':
                    localStorage.setItem('gameState', JSON.stringify({ player, tiles, inventory, day }));
                    break;
            }
        });

        document.addEventListener('load', () => {
            const savedState = localStorage.getItem('gameState');
            if (savedState) {
                const state = JSON.parse(savedState);
                player = state.player;
                tiles = state.tiles;
                inventory = state.inventory;
                day = state.day;
            }
            update();
        });
    </script>
</body>
</html>
